        public int CheckColorindex(int R, int G, int B)
        {
            List<double> distances = new List<double>();
            for (int i = 0; i < Red.Count; i++)
            {
                int a = Red[i] - R;
                int b = Green[i] - G;
                int c = Blue[i] - B;
                distances.Add(Math.Sqrt(a * a + b * b + c * c));
            }
            return distances.IndexOf(distances.Min())+1;
        }

        public List<int> FindIndexs(List<int> list, int item)
        {
            List<int> result = new List<int>();
            for (int i = 0; i < list.Count; i++)
            {
                if (list[i] == item)
                {
                    result.Add(i + 1);
                }
            }
            return result;
        }
